package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="membership_requests")
public class MembershipRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="applicant_name") private String applicantName; private String email; @Column(name="cv_url") private String cvUrl; @Column(length=5000) private String motivation; @Enumerated(EnumType.STRING) @Column(name="requested_type") private MemberType requestedType; private String establishment; @Column(name="origin_lab") private String originLab; @Column(length=2000) private String interests; @Column(length=4000) private String biography; @Column(name="preferred_team_id") private Long preferredTeamId; private String phone; @Enumerated(EnumType.STRING) private MembershipRequestStatus status = MembershipRequestStatus.PENDING; @Column(name="reviewed_by") private Long reviewedBy; @Column(name="reviewed_at") private LocalDateTime reviewedAt; private String decisionReason; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getApplicantName(){return applicantName;} public void setApplicantName(String applicantName){this.applicantName=applicantName;} public String getEmail(){return email;} public void setEmail(String email){this.email=email;} public String getCvUrl(){return cvUrl;} public void setCvUrl(String cvUrl){this.cvUrl=cvUrl;} public String getMotivation(){return motivation;} public void setMotivation(String motivation){this.motivation=motivation;} public MemberType getRequestedType(){return requestedType;} public void setRequestedType(MemberType requestedType){this.requestedType=requestedType;} public String getEstablishment(){return establishment;} public void setEstablishment(String establishment){this.establishment=establishment;} public String getOriginLab(){return originLab;} public void setOriginLab(String originLab){this.originLab=originLab;} public String getInterests(){return interests;} public void setInterests(String interests){this.interests=interests;} public String getBiography(){return biography;} public void setBiography(String biography){this.biography=biography;} public Long getPreferredTeamId(){return preferredTeamId;} public void setPreferredTeamId(Long preferredTeamId){this.preferredTeamId=preferredTeamId;} public String getPhone(){return phone;} public void setPhone(String phone){this.phone=phone;} public MembershipRequestStatus getStatus(){return status;} public void setStatus(MembershipRequestStatus status){this.status=status;} public Long getReviewedBy(){return reviewedBy;} public void setReviewedBy(Long reviewedBy){this.reviewedBy=reviewedBy;} public LocalDateTime getReviewedAt(){return reviewedAt;} public void setReviewedAt(LocalDateTime reviewedAt){this.reviewedAt=reviewedAt;} public String getDecisionReason(){return decisionReason;} public void setDecisionReason(String decisionReason){this.decisionReason=decisionReason;} }
